CREATE TABLE organizations (id uuid PRIMARY KEY, name text NOT NULL, slug text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, display_name text NOT NULL, password_hash text NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organization_memberships (organization_id uuid NOT NULL REFERENCES organizations(id), user_id uuid NOT NULL REFERENCES users(id), role text NOT NULL CHECK (role IN ('owner','administrator','team_member','read_only_analyst','contractor')), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (organization_id,user_id));
CREATE TABLE sessions (id_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), organization_id uuid NOT NULL REFERENCES organizations(id), expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), ip_hash text, user_agent text);
CREATE INDEX sessions_user_active_idx ON sessions(user_id, expires_at) WHERE revoked_at IS NULL;
CREATE TABLE login_history (id uuid PRIMARY KEY, user_id uuid REFERENCES users(id), email_hash text NOT NULL, outcome text NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), ip_hash text, user_agent text);
CREATE TABLE audit_logs (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), actor_user_id uuid REFERENCES users(id), action text NOT NULL, resource_type text NOT NULL, resource_id text, outcome text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_org_created_idx ON audit_logs(organization_id, created_at DESC);
